    return [...text].map(char => {
        const glyph = glyphFor(role, char);
        const path = `<path transform="translate(${cursor.toFixed(3)} ${y}) scale(${size / face.em} ${-size / face.em})" d="${glyph.d}"/>`;
        cursor += glyph.advance * size / face.em;
